BEGIN READ ONLY; SET LOCAL statement_timeout='20s'; SELECT clock_timestamp() captured_at,
(SELECT count(*) FROM public.tenant_staff_identity_bindings) staff_bindings,
(SELECT count(*) FROM public.tenant_customer_identity_providers WHERE purpose='staff' AND is_active) active_staff_providers,
(SELECT count(*) FROM public.integration_api_clients c WHERE status='active' AND revoked_at IS NULL AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at>clock_timestamp()) AND EXISTS(SELECT FROM unnest(c.scopes) s WHERE s~'^staff_(users|customers|cases)\.(read|write)$')) active_explicit_staff_clients,
(SELECT count(*) FROM public.integration_api_clients WHERE jsonb_typeof(metadata->'staff_tenant_auth')='object') registered_staff_auth_clients;
COMMIT;
